begin;

create table public."Dim_TipoCuenta" (
  "Id_Tipo_Cuenta" smallint generated by default as identity primary key,
  "DESCRIPCION_TIPO_CUENTA" varchar not null,
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public."Dim_TipoCuenta" is 'Catálogo de tipos de cuenta para el módulo Servicios.';
comment on column public."Dim_TipoCuenta".estado is 'Estado del registro: 1 activo, 0 inactivo.';

alter table public."Dim_TipoCuenta" enable row level security;
revoke all on table public."Dim_TipoCuenta" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_TipoCuenta" to authenticated;

create policy dim_tipo_cuenta_select_admin on public."Dim_TipoCuenta"
for select to authenticated using ((select private.is_admin()));
create policy dim_tipo_cuenta_insert_admin on public."Dim_TipoCuenta"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_tipo_cuenta_update_admin on public."Dim_TipoCuenta"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_tipo_cuenta_delete_admin on public."Dim_TipoCuenta"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_tipo_cuenta_updated_at()
returns trigger language plpgsql set search_path = pg_catalog as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_tipo_cuenta_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_tipo_cuenta_updated_at
before update on public."Dim_TipoCuenta"
for each row execute function private.set_dim_tipo_cuenta_updated_at();

insert into public."Dim_TipoCuenta" ("Id_Tipo_Cuenta", "DESCRIPCION_TIPO_CUENTA") values
  (1, 'PLANILLAS'),
  (2, 'SERVICIOS'),
  (3, 'AGOTAMIENTO Y DEPRECIACIÓN'),
  (4, 'INTERESES'),
  (5, 'ALMACENES'),
  (6, 'VENTAS'),
  (7, 'ADMINISTRATIVAS'),
  (8, 'MAQUINARIA'),
  (9, 'COSTO INDIRECTO'),
  (10, 'CAMIONETAS ADM'),
  (11, 'POZOS');

select setval(
  pg_get_serial_sequence('public."Dim_TipoCuenta"', 'Id_Tipo_Cuenta'),
  (select max("Id_Tipo_Cuenta") from public."Dim_TipoCuenta"),
  true
);

do $$
declare v_sequence regclass := pg_get_serial_sequence('public."Dim_TipoCuenta"', 'Id_Tipo_Cuenta');
begin execute format('grant usage, select on sequence %s to authenticated', v_sequence); end;
$$;

commit;
